import pandas as pd

def clean(df):
    df = df.copy()
    df = df.drop_duplicates().reset_index(drop=True)

    if "Category" in df.columns:
        df["Category"] = df["Category"].astype("string").str.strip()
        df["Category"] = df["Category"].replace({
            "Office Suplies": "Office Supplies",
            "Accesories": "Accessories",
        })

    if "Region" in df.columns:
        df["Region"] = df["Region"].astype("string").str.strip()
        df.loc[df["Region"].isin(["", "nan", "None"]), "Region"] = pd.NA

    if "Date" in df.columns:
        df["Date"] = pd.to_datetime(df["Date"], errors="coerce")

    for col in ["Quantity", "Price", "Revenue"]:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce")

    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=["Category", "Price"])
    result = d.groupby("Category", dropna=True)["Price"].mean()
    return {str(k): float(v) for k, v in result.items()}
